.sidebar {
  container: sidebar / inline-size;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  height: 100%;
  background: #f5f6f9;
  border-right: 1px solid #dfe3ea;
  padding: 1rem 0.75rem;
  box-sizing: border-box;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.switcherLabel {
  display: block;
}

.switcherSelect {
  width: 100%;
  border: 1px solid #c9cfdb;
  border-radius: 0.375rem;
  background: #fff;
  padding: 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: #1f2a44;
}

.nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.navItem {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  border-radius: 0.375rem;
  padding: 0.5rem 0.625rem;
  color: #1f2a44;
  font-size: 0.875rem;
  font-weight: 600;
  background: #e7e9ef;
}

.navIcon {
  flex-shrink: 0;
}

.navLabel {
  white-space: nowrap;
}

/* Below this width there isn't room for both the icon and the label —
   the label drops and the icon alone still identifies the section. This
   is driven by the sidebar's own box, never the viewport, so an embedding
   page that gives the sidebar less room re-tiers it correctly too. */
@container sidebar (width < 12rem) {
  .navLabel {
    display: none;
  }

  .navItem {
    justify-content: center;
  }
}

